SELECT pg_attribute.attnum AS index, attname AS field, typname AS type, atttypmod-4 as length, NOT attnotnull AS "null", adsrc AS def FROM pg_attribute, pg_class, pg_type, pg_attrdef, pg_namespace WHERE pg_class.oid=attrelid AND pg_type.oid=atttypid AND attnum>0 AND pg_class.oid=adrelid AND adnum=attnum AND atthasdef='t' AND pg_namespace.oid=relnamespace  AND ((nspname=current_schema() AND lower(relname)='codigosfiscais') OR lower(nspname || '.' || relname)   = 'codigosfiscais') UNION SELECT pg_attribute.attnum AS index, attname AS field, typname AS type, atttypmod-4 as length, NOT attnotnull AS "null", '' AS def FROM pg_attribute, pg_class, pg_type, pg_namespace  WHERE pg_class.oid=attrelid AND pg_type.oid=atttypid AND attnum>0 AND atthasdef='f' AND pg_namespace.oid=relnamespace  AND ((nspname=current_schema() AND lower(relname)='codigosfiscais') OR lower(nspname || '.' || relname)   = 'codigosfiscais');
SELECT i.indexrelid AS index, t1.relname AS name, t2.relname AS table, indisunique AS "unique", indkey AS fields FROM pg_index AS i, pg_class AS t1, pg_class AS t2, pg_namespace  WHERE i.indexrelid=t1.oid AND i.indrelid=t2.oid AND pg_namespace.oid=t2.relnamespace  AND ((nspname=current_schema() AND lower(t2.relname)='codigosfiscais') OR lower(nspname || '.' || t2.relname)   = 'codigosfiscais');
