SELECT c.codigo, c.codigovisual,  c.descricao,  (select gr.descricao from grades gr where gr.codigo = c.grade1) as linha,  (select gr.descricao from grades gr where gr.codigo = c.grade2) as coluna,  c.grade1,  c.grade2,  cast(0 as integer) as codigopreco,  (select m1.valor  from estadosicms m1  where m1.icms = c.icms  and m1.estado ='SC') as icms,  c.icms as codigoicms,  (select ti.valor from tributosicms ti where ti.codigo = c.incidencia) as incidencia,  c.csosn,  (select m1.valor from estadosicms m1  where m1.icms = c.icms  and m1.estado ='SC') as aliquotaicmscalculopreco,  c.ipi,  (select i.aliquota  from ipi i  where i.codigo = c.ipi) as aliquotaipi,  c.composto,  c.aliquotapis,  c.aliquotacofins,  c.markup as markup_produto,  g.markup as markup_grupo,  g.calcularpreco,  (select e.precocomicms  from estoques e  where e.produto = (select p.codigo  from produtos p  where p.caracteristica = c.codigo limit 1)  and e.filial = 1) as preco,  c.grupo,  c.classe,  (case when g.naoreplicar then true  else cl.naoreplicar end) as naoreplicar  FROM caracteristicas c, grupos g, classes cl WHERE c.grupo = g.codigo  and c.classe = cl.codigo  and c.codigo = '2219'  ;
