select pnpnfe.*,   pnpnfe.qtdeestoque -  coalesce((select sum(pnpnfeitems.quantidade)  from produtosnotaspagnfeitems pnpnfeitems  where pnpnfeitems.codigonota = pnpnfe.codigonota  and pnpnfeitems.numerosequencianfe = pnpnfe.numero  and pnpnfeitems.produto is not null),0) as SaldoQuantidade,   /* O USO DOS CAMPOS ABAIXO SE DÁ PARA O LANÇAMENTO E LINHAS E COLUNAS */   cast(null as numeric(11,3)) as QuantidadeselecionadaLC,  cast(null as numeric(11,3)) as QuantidadeselecionadaLC_Copia,  cast(null as numeric(11,3)) as SaldoQuantidadeLC,   (Select cf.descricao  from codigosfiscais cf  where cf.codigo = pnpnfe.CFOP) as DescricaoCFOP,   (Select ipi.descricao  from ipi  where ipi.codigo = pnpnfe.ipi  and ipi.classificacaofiscal = pnpnfe.ncmfornecedor) as DescricaoIPI   from produtosnotaspagnfe pnpnfe where pnpnfe.codigonota = 0 order by pnpnfe.numero ;
select ipi.*,  cast(trim(cast(ipi.codigo as varchar))||' - '||cast(ipi.descricao as varchar(30)) as varchar(40)) as codigodescricao from ipi where ipi.classificacaofiscal in ( select distinct pnpnfe.ncmfornecedor from produtosnotaspagnfe pnpnfe where pnpnfe.codigonota = 4048) order by ipi.codigo desc  ;
select pnpnfel.*,   (select sum(pnpnfei.quantidade)  from produtosnotaspagnfeitems pnpnfei  where pnpnfei.codigonota = pnpnfel.codigonota  and pnpnfei.numerosequencianfe = pnpnfel.numerosequencianfe  and pnpnfei.nlote = pnpnfel.nlote) as qtAtribuida,   (select sum(pnpnfei.qtdeestoque)  from produtosnotaspagnfeitems pnpnfei  where pnpnfei.codigonota = pnpnfel.codigonota  and pnpnfei.numerosequencianfe = pnpnfel.numerosequencianfe  and pnpnfei.nlote = pnpnfel.nlote) as qtAtribuidaEstoque,   pnpnfel.dval is not null as nulo_dval,  pnpnfel.dfab is not null as nulo_dfab,   pnpnfel.nlote as nLoteAnterior   from produtosnotaspagnfelotes pnpnfel where pnpnfel.codigonota = 0 order by pnpnfel.numerosequencianfe ;
select pnpnfeitems.*,  p.codigovisual as produtovisual,  p.descricao as descricaoproduto,  (select ipi.classificacaofiscal from ipi where ipi.codigo = c.ipi) as ncmempresa,  n.descricao as descricaonatureza,  cf.descricao as descricaocodigofiscal,  n.tipomovimento,   p.valorgrade1 as valorgrade1,  p.valorgrade2 as valorgrade2,  p.caracteristica as caracteristica,  c.codigovisual as caracteristicavisual,  c.gerenciarloteevalidade,    (select m.operacao from tiposmovimentos m where m.codigo = n.tipomovimento) as operacao,   (select (pp.preco * (100 - coalesce(pp.desconto,0)) / 100)  from produtospedidos pp  where pp.pedido = pnpnfeitems.pedido and pp.produto = pnpnfeitems.produto and pp.numero = pnpnfeitems.numeroprodutonopedido) as PrecoUnitarioPedido,    (Select ipi.descricao  from ipi  where ipi.codigo = pnpnfeitems.ipi  and ipi.classificacaofiscal = pnpnfe.ncmfornecedor) as DescricaoIPI,   pnpnfe.ncmfornecedor,    (select true  from produtospedidos pp  where pp.pedido = pnpnfeitems.pedido and pp.produto = pnpnfeitems.produto and pp.numero = pnpnfeitems.numeroprodutonopedido) as pedidoOK  from produtosnotaspagnfeitems pnpnfeitems  join produtosnotaspagnfe pnpnfe  on pnpnfeitems.codigonota = pnpnfe.codigonota  and pnpnfeitems.numerosequencianfe = pnpnfe.numero   left join (produtos p  join caracteristicas c  on p.caracteristica = c.codigo)  on pnpnfeitems.produto = p.codigo   left join naturezas n  on pnpnfeitems.natureza = n.codigo   left join codigosfiscais cf  on pnpnfeitems.codigofiscal = cf.codigo  where pnpnfeitems.codigonota = 0 order by pnpnfeitems.numerosequencianfe, pnpnfeitems.numero ;
select pnpis.* from produtosnotaspagnfeitemssituacao pnpis where pnpis.codigonota = 0 order by pnpis.numerosequencianfe, pnpis.numerosequencianfeitens,pnpis.numero ;
select pdnp.* from pedidosnotaspag pdnp where pdnp.codigonota = 0 order by pdnp.pedido ;
SELECT false;
select produtosnotaspagnfeitemssituacao_proximocodigo() as codigo ;
SELECT pg_attribute.attnum AS index, attname AS field, typname AS type, atttypmod-4 as length, NOT attnotnull AS "null", adsrc AS def FROM pg_attribute, pg_class, pg_type, pg_attrdef, pg_namespace WHERE pg_class.oid=attrelid AND pg_type.oid=atttypid AND attnum>0 AND pg_class.oid=adrelid AND adnum=attnum AND atthasdef='t' AND pg_namespace.oid=relnamespace  AND ((nspname=current_schema() AND lower(relname)='seriesfiliais') OR lower(nspname || '.' || relname)   = 'seriesfiliais') UNION SELECT pg_attribute.attnum AS index, attname AS field, typname AS type, atttypmod-4 as length, NOT attnotnull AS "null", '' AS def FROM pg_attribute, pg_class, pg_type, pg_namespace  WHERE pg_class.oid=attrelid AND pg_type.oid=atttypid AND attnum>0 AND atthasdef='f' AND pg_namespace.oid=relnamespace  AND ((nspname=current_schema() AND lower(relname)='seriesfiliais') OR lower(nspname || '.' || relname)   = 'seriesfiliais');
SELECT i.indexrelid AS index, t1.relname AS name, t2.relname AS table, indisunique AS "unique", indkey AS fields FROM pg_index AS i, pg_class AS t1, pg_class AS t2, pg_namespace  WHERE i.indexrelid=t1.oid AND i.indrelid=t2.oid AND pg_namespace.oid=t2.relnamespace  AND ((nspname=current_schema() AND lower(t2.relname)='seriesfiliais') OR lower(nspname || '.' || t2.relname)   = 'seriesfiliais');
select filial,  valor,  numeroinicial,  numerofinal,  modelonota from seriesfiliais where filial = 1 and  valor = '1' for update ;
SELECT sf.fornecedor,  sf.serie,  sf.modelodoctofiscal FROM seriesfornecedores sf WHERE (sf.fornecedor = 358) and  (sf.serie = '1') and  ('F' = 'C') UNION SELECT sc.cliente,  sc.serie,  sc.modelodoctofiscal FROM seriesclientes sc WHERE (sc.cliente =358) and  (sc.serie ='1') and  ('C' ='C') union select sf.filial,  sf.valor as serie,  sf.modelodoctofiscal from seriesfiliais sf where (sf.filial = 1) and  (sf.valor = '1') and  ('C' = 'C') and  ((select count(*)  from seriesclientes  where cliente = 358) = 0) UNION SELECT sf.filial,  sf.valor as serie,  sf.modelodoctofiscal FROM seriesfiliais sf WHERE (sf.filial = 358) and  (sf.valor = '1') and  ('L' = 'C') ORDER BY serie ;
select f.codigo,  f.nome, f.razao,  f.estado,  f.pessoanumero,  f.estrangeiro,  f.pessoatipo,  f.inscricaoestadual,  f.tipo,  f.markup,  f.rua,  f.bairro,  f.cidade,  f.cep,  f.fonenumero,  f.foneddd,   f.numero,  f.complemento,   (select b.nome  from bairros b  where b.estado = f.estado  and b.cidade = f.cidade  and b.codigo = f.bairro) as NomeBairro,   (select c.nome  from cidades c  where c.estado = f.estado  and c.codigo = f.cidade) as NomeCidade,    (select c.CodigoIBGE  from cidades c  where c.estado = f.estado  and c.codigo = f.cidade) as CidadeIBGE,   (select d.tipofornecimento[1]='T'  from fornecedores d  where d.codigo = f.codigo  ) as tipofornecimento_T,  (select d1.grupofornecedor  from fornecedores d1  where d1.codigo = f.codigo  ) as grupofornecedor,  f.debito,  (select descricao from planocontas pl where pl.codigo=f.debito) as descricaodebitoplanocontas,  (select classificacao from planocontas pl where pl.codigo=f.debito) as classificacaodebitoplanocontas,  f.credito,  (select descricao from planocontas pl where pl.codigo=f.credito) as descricaocreditoplanocontas,  (select classificacao from planocontas pl where pl.codigo=f.credito) as classificacaocreditoplanocontas,  coalesce((select fo.NaoSubstituto from fornecedores fo where fo.codigo = f.codigo and f.tipo='F'),true) as NaoSubstituto,   coalesce((select fr.distribuidor  from fornecedores fr  where fr.codigo = f.codigo  and f.tipo='F'  ),false) as distribuidor,  f.nosimples,   case when 'C' = 'F' then  (select fr.crt  from fornecedores fr  where fr.codigo = f.codigo  and 'F' = 'C'  )  when 'C' = 'L' then  (select fl.regimetributario  from filiais fl  where fl.codigo = f.codigo  and 'L' = 'C'  )  when 'C' = 'C' then  case when f.nosimples then cast(1 as smallint) else cast(3 as smallint) end  end as crt,   (case when f.tipo='C' then  (select cl.contribicms  from clientes cl  where cl.codigo = f.codigo)  when f.tipo='F' then  (select fo.contribicms  from fornecedores fo  where fo.codigo = f.codigo)  when f.tipo='L' then  (select fi.contribicms  from filiais fi  where fi.codigo = f.codigo)  end) as contribicms,  f.email,  f.suframa,  coalesce((select fo.dda from fornecedores fo where fo.codigo = f.codigo and f.tipo='F'),false) as dda    from vfornecedores f where (f.codigo = 358) and  (f.tipo = 'C') order by UPPER(TO_ASCII(coalesce(f.razao,f.nome),'LATIN1')) ;
