select n.filial,  n.serie,  n.dadofiscal,  n.numero,   df.cliente,  df.tipocliente,  df.valortotal,  df.valorprodutos,  df.valorvista,  df.desconto,  df.valoripi,  df.nome,  df.chv_nfe,  df.data,   case when (NULL <> '') and (1 <>0) then  (select pdf.numero  from produtosdadosfiscais pdf  where pdf.dadofiscal = n.dadofiscal  and pdf.produto = NULL  and pdf.filial = 1)  else  cast(null as integer)  end as numitemdocfiscalsaida  from dadosfiscais df  join notas n  on df.numero = n.dadofiscal  where n.filial = 1  and (n.serie = '1' or coalesce('1','')='')  and n.numero = 15249    and df.cliente = 358 and df.tipocliente = 'C' and df.dadofiscalreferenciado is null  ;
