select pnp.codigonota,  pnp.produto,  pnp.numero,   /* as regras para definição do cst, cclasstrib e vbs são as mesmas, pode-se pegar  o cst e cclasstrib de um dos três cbs, ibsuf ou ibsmun */   (select teii.codigo_cst  from trib_entrada_item_imposto teii  join trib_imposto ti  on teii.id_imposto = ti.id_imposto    where pnp.codigonota = teii.codigonota  and pnp.numero = teii.numero  and pnp.produto = teii.produto  and ti.codigo = 'CBS') as codigo_cst_cbsibs,   (select teii.cclasstrib  from trib_entrada_item_imposto teii  join trib_imposto ti  on teii.id_imposto = ti.id_imposto   where pnp.codigonota = teii.codigonota  and pnp.numero = teii.numero  and pnp.produto = teii.produto  and ti.codigo = 'CBS') as cclasstrib_cbsibs,   (select teii.vbc  from trib_entrada_item_imposto teii  join trib_imposto ti  on teii.id_imposto = ti.id_imposto   where pnp.codigonota = teii.codigonota  and pnp.numero = teii.numero  and pnp.produto = teii.produto  and ti.codigo = 'CBS') as vbc_cbsibs,    (select teii.paliq  from trib_entrada_item_imposto teii  join trib_imposto ti  on teii.id_imposto = ti.id_imposto   where pnp.codigonota = teii.codigonota  and pnp.numero = teii.numero  and pnp.produto = teii.produto  and ti.codigo = 'CBS') as paliq_cbs,   (select teii.vimposto  from trib_entrada_item_imposto teii  join trib_imposto ti  on teii.id_imposto = ti.id_imposto   where pnp.codigonota = teii.codigonota  and pnp.numero = teii.numero  and pnp.produto = teii.produto  and ti.codigo = 'CBS') as vimposto_cbs,   (select teii.paliq  from trib_entrada_item_imposto teii  join trib_imposto ti  on teii.id_imposto = ti.id_imposto   where pnp.codigonota = teii.codigonota  and pnp.numero = teii.numero  and pnp.produto = teii.produto  and ti.codigo = 'IBSUF') as paliq_ibsuf,   (select teii.vimposto  from trib_entrada_item_imposto teii  join trib_imposto ti  on teii.id_imposto = ti.id_imposto   where pnp.codigonota = teii.codigonota  and pnp.numero = teii.numero  and pnp.produto = teii.produto  and ti.codigo = 'IBSUF') as vimposto_ibsuf,   (select teii.paliq  from trib_entrada_item_imposto teii  join trib_imposto ti  on teii.id_imposto = ti.id_imposto   where pnp.codigonota = teii.codigonota  and pnp.numero = teii.numero  and pnp.produto = teii.produto  and ti.codigo = 'IBSMUN') as paliq_ibsmun,   (select teii.vimposto  from trib_entrada_item_imposto teii  join trib_imposto ti  on teii.id_imposto = ti.id_imposto   where pnp.codigonota = teii.codigonota  and pnp.numero = teii.numero  and pnp.produto = teii.produto  and ti.codigo = 'IBSMUN') as vimposto_ibsmun  from produtosnotaspag pnp where pnp.codigonota = 4048  and pnp.produto = '2219'  and pnp.numero = 1 ;
