i.codigo = 'IBSUF') as vimposto_ibsuf,   (select teii.paliq  from trib_entrada_item_imposto teii  join trib_imposto ti  on teii.id_imposto = ti.id_imposto   where pnp.codigonota = teii.codigonota  and pnp.numero = teii.numero  and pnp.produto = teii.produto  and ti.codigo = 'IBSMUN') as paliq_ibsmun,   (select teii.vimposto  from trib_entrada_item_imposto teii  join trib_imposto ti  on teii.id_imposto = ti.id_imposto   where pnp.codigonota = teii.codigonota  and pnp.numero = teii.numero  and pnp.produto = teii.produto  and ti.codigo = 'IBSMUN') as vimposto_ibsmun  from produtosnotaspag pnp where pnp.codigonota = 4048  and pnp.produto = '337400'  and pnp.numero = 5 ;
