select /* as regras para definição do cst, cclasstrib e vbs são as mesmas, pode-se pegar  o cst e cclasstrib de um dos três cbs, ibsuf ou ibsmun */   sum((select teti.vbc  from trib_entrada_total_imposto teti  join trib_imposto ti  on teti.id_imposto = ti.id_imposto   where np.codigo = teti.codigonota  and ti.codigo = 'CBS')) as vbc_cbsibs,    sum((select teti.vimposto  from trib_entrada_total_imposto teti  join trib_imposto ti  on teti.id_imposto = ti.id_imposto   where np.codigo = teti.codigonota  and ti.codigo = 'CBS')) as vimposto_cbs,    sum((select teti.vimposto  from trib_entrada_total_imposto teti  join trib_imposto ti  on teti.id_imposto = ti.id_imposto   where np.codigo = teti.codigonota  and ti.codigo = 'IBSUF')) as vimposto_ibsuf,   sum((select teti.vimposto  from trib_entrada_total_imposto teti  join trib_imposto ti  on teti.id_imposto = ti.id_imposto   where np.codigo = teti.codigonota  and ti.codigo = 'IBSMUN')) as vimposto_ibsmun   from notaspag np where np.codigo = 4048   ;
