select e.produto,  e.filial,  e.datacompra,  e.qtdecompra,  e.precosemicms,  e.precocomicms,   e.financeiro,   e.aliquotaipi,   e.ultimaentrada,  e.emestoque,  e.reservado,  e.transito,  e.demonstracao,  e.conserto,  e.futuro,  e.danificada,  e.estoquefisico,    /* (case when inclusao then*/  /* Primeiro -> Tenta pegar com a existencia do efc e codigonota, na inclusão não existe, pegará pelo último movto */   coalesce(    (select m.futuro  from movimentos m  where m.produto = e.produto  and m.filial = e.filial  and m.codigonota = 4048  and m.tipomovimento = 'EFC'  order by numero limit 1),  /* Segundo - > Pelo último movimento */    (select m.futuro  FROM movimentos m,  (  select m2.produto,m2.filial,max(data) as data,max(lancto) as lancto  from movimentos m2  where m2.produto=e.produto  AND m2.filial=e.filial  and data < (cast('2026-08-14' as date)+1)   /*  and case when inclusao then true  else m2.codigonota = 4048  and m2.numerocontrole = numerocontrole  end  */   group by produto,filial,data  order by data desc  limit 1  ) as m1  WHERE m.produto=m1.produto  AND m.filial=m1.filial  AND m.data=m1.data  and m.lancto=m1.lancto))  /*  else   (select m.futuro  from movimentos m  where m.produto = e.produto  and m.filial = e.filial  and m.codigonota = 4048  and m.tipomovimento = 'EFC'  order by numero limit 1)    end) */   as futuro_na_data_inclusao    from estoques e where  ((e.produto = 2219)and(e.filial = 1))or((e.produto = 2388)and(e.filial = 1))or((e.produto = 2389)and(e.filial = 1))or((e.produto = 2784)and(e.filial = 1))or((e.produto = 337400)and(e.filial = 1))or((e.produto = 337500)and(e.filial = 1))or((e.produto = 337600)and(e.filial = 1))or((e.produto = 337700)and(e.filial = 1))or((e.produto = 337800)and(e.filial = 1))or((e.produto = 360100)and(e.filial = 1))or((e.produto = 369800)and(e.filial = 1))or((e.produto = 369900)and(e.filial = 1))or((e.produto = 370000)and(e.filial = 1))or((e.produto = 374200)and(e.filial = 1))or((e.produto = 374300)and(e.filial = 1))or((e.produto = 374400)and(e.filial = 1))or((e.produto = 389300)and(e.filial = 1))or((e.produto = 393600)and(e.filial = 1))or((e.produto = 394000)and(e.filial = 1))or((e.produto = 394100)and(e.filial = 1))or((e.produto = 394200)and(e.filial = 1))or((e.produto = 394300)and(e.filial = 1))or((e.produto = 394400)and(e.filial = 1))or((e.produto = 394500)and(e.filial = 1))or((e.produto = 400200)and(e.filial = 1))or((e.produto = 405400)and(e.filial = 1))or((e.produto = 405500)and(e.filial = 1))or((e.produto = 405600)and(e.filial = 1))  for update ;
