select m.numero,  m.produto,  m.loteproduto,  m.numerocontrole,  m.filial,  m.data,  m.quantidade,  m.tipomovimento,  m.operacao,  m.emestoque,  m.reservado,  m.transito,  m.demonstracao,  m.conserto,  m.futuro,  m.danificada,  m.estoquefisico,  m.financeiro,  m.valor,  m.precocomicms,  m.precosemicms,  m.aliquotaipi,  m.referencia,  m.trfproduto,  m.trffilial,  m.trfmovimento,  m.codigonota,  m.moeda,  m.valormoeda,  m.valorultimacompra,  false as ok  from movimentos m where true  and m.codigonota = 4048 order by produto,filial,numero ;
