select pf.*, p.codigovisual as produtovisual,   case when pf.serienota is not null and pf.numeronota is not null then  false  else  (select EXISTS  (select pnp.produto  from produtosnotaspag pnp  join produtosnotaspagnfeitems pnpnfeitems  join produtosnotaspagnfe pnpnfe  on pnpnfeitems.codigonota = pnpnfe.codigonota  and pnpnfeitems.numerosequencianfe = pnpnfe.numero  on pnp.codigonota = pnpnfeitems.codigonota  and pnp.numerosequencianfe = pnpnfeitems.numerosequencianfe  and pnp.numerosequencianfeitens = pnpnfeitems.numero  join notaspag np  on pnp.codigonota = np.codigo  where np.fornecedor = pf.fornecedor  and np.tipofornecedor = pf.tipofornecedor  and pnp.produto = pf.produto  and pnpnfe.produtonofornecedor = pf.produtonofornecedor  and pnpnfe.descricaofornecedor = pf.descricaonofornecedor   and not (np.serie = '1' and np.Numero = 15312)  limit 1) as temp)  end  as ExisteOutrasVinculacoes,   (select count(*)  from produtosnotaspag pnp  join produtosnotaspagnfeitems pnpnfeitems  join produtosnotaspagnfe pnpnfe  on pnpnfeitems.codigonota = pnpnfe.codigonota  and pnpnfeitems.numerosequencianfe = pnpnfe.numero  on pnp.codigonota = pnpnfeitems.codigonota  and pnp.numerosequencianfe = pnpnfeitems.numerosequencianfe  and pnp.numerosequencianfeitens = pnpnfeitems.numero  join notaspag np  on pnp.codigonota = np.codigo  where np.fornecedor = pf.fornecedor  and np.tipofornecedor = pf.tipofornecedor  and pnp.produto = pf.produto  and pnpnfe.produtonofornecedor = pf.produtonofornecedor  and pnpnfe.descricaofornecedor = pf.descricaonofornecedor  and (np.serie = '1' and np.Numero = 15312)  ) as NumerodeVinculacoesNaNota,   (select count(*)  from produtosnotaspag pnp  join produtosnotaspagnfeitems pnpnfeitems  join produtosnotaspagnfe pnpnfe  on pnpnfeitems.codigonota = pnpnfe.codigonota  and pnpnfeitems.numerosequencianfe = pnpnfe.numero  on pnp.codigonota = pnpnfeitems.codigonota  and pnp.numerosequencianfe = pnpnfeitems.numerosequencianfe  and pnp.numerosequencianfeitens = pnpnfeitems.numero  join notaspag np  on pnp.codigonota = np.codigo  where np.fornecedor = pf.fornecedor  and np.tipofornecedor = pf.tipofornecedor  and pnp.produto = pf.produto  and pnpnfe.produtonofornecedor = pf.produtonofornecedor  and pnpnfe.descricaofornecedor = pf.descricaonofornecedor   ) as NumerodeOcorrencias,   false as flag  from produtosfornecedores pf  join produtos p  join caracteristicas c  on p.caracteristica = c.codigo  on pf.produto = p.codigo where true   /*  and pf.produtonofornecedor = _produtonofornecedor  and pf.descricaonofornecedor = _descricaonofornecedor  and pf.infadprod = _infadprod  and pf.produto = _produto  and pf.fornecedor = _fornecedor  and pf.tipofornecedor = _tipofornecedor */     /*  and pf.produtonofornecedor = _produtonofornecedor  and pf.descricaonofornecedor = _descricaonofornecedor  and pf.infadprod = _infadprod  and pf.fornecedor = _fornecedor  and pf.tipofornecedor = _tipofornecedor and pf.data is not null  and ((pf.serienota is null or pf.serienota = '1') and (pf.numeronota is null or pf.NumeroNota = 15312)) */    and pf.fornecedor = 358 and pf.tipofornecedor = 'C' and ((pf.serienota is null or pf.serienota = '1') and (pf.numeronota is null or pf.NumeroNota = 15312))and (pf.produtonofornecedor, pf.descricaonofornecedor, pf.produto) in (('0','',0))  /*  and pf.fornecedor = _fornecedor  and pf.tipofornecedor = _tipofornecedor  and (pf.produtonofornecedor, pf.descricaonofornecedor, pf.produto) in ()  */   order by pf.data desc ;
