fornecedorparaiss", "chv_nfe", "valorservicos_nt", "valorterceiros", "valorpis", "valorcofins", "numcancelamentonfe", "datahoraemissao", "regimetributario", "numinutilizacaonfe", "baseicmscalculada", "valoricmscalculada", "baseicmssubstituicaocalculada", "valoricmssubstituicaocalculada", "valoripicalculada", "valornotacalculada", "distribuidor", "nosimples", "dhprocnfe", "hsaient", "crt", "requernfsaida", "numeroregistrodescontoalterado", "statusnfe", "cancelamentonfforaprazolegal", "dadofiscalreferenciado", "icmsbasecalculo_dev", "icmsvalor_dev", "naoutilizarobsautomaticas", "vbcstretdesp", "vicmsstretdesp", "clientecontribicms", "datahoragravacao", "descontoitem", "vfcp", "vfcpst", "vfcpstret", "tipo", "localretirada_pessoatipo", "localentrega_pessoatipo", "estrangeiro") VALUES (4048, 358, '1', 'C', 1, 1914, '2026-08-14', 'SC', 38744.11, 0, 4.43, NULL, '18258209000115', '257.054.367', NULL, NULL, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, 38094.26, 'RETORNO DE MERCADORIA OU BEM REMETIDO PARA EXPOSIÇÃO OU FEIRA', 't', 'MATERIAL PARA FEIRA EXPO HOSPITAL BRASIL 2026,  DE 11 A 13 DE AGOSTO DE 2026, ICMS ISENTO CONFORME ANEXO II ART. 4, INC VII RICMSC, IPI SUSPENSO CONFORME ART 43 INC II RIPI DECRETO 1212/20101790/97', 1494, NULL, NULL, 'R', 150, NULL, 'N', NULL, 654.28, NULL, 0, 0, NULL, '1', 3.1, '55', 25630182, 2, 1, 1, 4, 1, 1, 0, 'BETA', NULL, 251.8, 1162.3, 'Passa Vinte', 'Palhoça', 4211900, 1058, 'Brasil', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 50, '', 'MATERIAL PARA FEIRA EXPO HOSPITAL BRASIL 2026,  DE 11 A 13 DE AGOSTO DE 2026, ICMS ISENTO CONFORME ANEXO II ART. 4, INC VII RICMSC, IPI SUSPENSO CONFORME ART 43 INC II RIPI DECRETO 1212/20101790/97', NULL, NULL, NULL, 15312, '2026-08-14', 'Cirúrgica Ceron', 'Rua Alberto Laureano Henrich', 14136, 8589, 87902, 33420121, 48, '', NULL, '4226081825820900011555