SELECT pg_attribute.attnum AS index, attname AS field, typname AS type, atttypmod-4 as length, NOT attnotnull AS "null", adsrc AS def FROM pg_attribute, pg_class, pg_type, pg_attrdef, pg_namespace WHERE pg_class.oid=attrelid AND pg_type.oid=atttypid AND attnum>0 AND pg_class.oid=adrelid AND adnum=attnum AND atthasdef='t' AND pg_namespace.oid=relnamespace  AND ((nspname=current_schema() AND lower(relname)='produtosdadosfiscais') OR lower(nspname || '.' || relname)   = 'produtosdadosfiscais') UNION SELECT pg_attribute.attnum AS index, attname AS field, typname AS type, atttypmod-4 as length, NOT attnotnull AS "null", '' AS def FROM pg_attribute, pg_class, pg_type, pg_namespace  WHERE pg_class.oid=attrelid AND pg_type.oid=atttypid AND attnum>0 AND atthasdef='f' AND pg_namespace.oid=relnamespace  AND ((nspname=current_schema() AND lower(relname)='produtosdadosfiscais') OR lower(nspname || '.' || relname)   = 'produtosdadosfiscais');
