select p.codigo as produto,  p.CodigoVisual as produtovisual,  p.descricao,  p.valorgrade1,  p.valorgrade2,  (select ti.valor from tributosicms ti where ti.codigo = c.incidencia) as incidencia,  c.csosn,  (select i.aliquota from ipi i where i.codigo = c.ipi) as aliquotaipi,  c.ipicst,  c.piscst,  c.cofinscst,  pdf.dadofiscal as NumeroDocumentoTabela,  pdf.numero as NumeroProdutoTabela,  c.unidade,  g.observacoesentrada,  c.gerenciarloteevalidade  from produtosdadosfiscais pdf  join (produtos p  left join precos pr  on p.caracteristica = pr.caracteristica  and p.preco = pr.codigo)   join caracteristicas c  join grupos g  on c.grupo = g.codigo   on p.caracteristica = c.codigo  on pdf.produto = p.codigo  where pdf.dadofiscal = 15406 and (pdf.numero = NULL or NULL is null)   AND ( upper(to_ascii(p.codigovisual,'latin1')) = upper(to_ascii('405500','latin1')) or   p.codigo in (select pcb.produto  from produtoscodigobarras pcb  where pcb.codigobarras = '405500')  or (p.caracteristica = NULL and p.valorgrade1 = NULL and p.valorgrade2 = NULL)    )    and (pdf.dadofiscal, pdf.numero, pdf.produto) not in ((15406, 1, 2219), (15406, 2, 2388), (15406, 3, 2389), (15406, 4, 2784), (15406, 5, 337400), (15406, 6, 337500), (15406, 7, 337600), (15406, 8, 337700), (15406, 9, 337800), (15406, 10, 360100), (15406, 11, 369800), (15406, 12, 369900), (15406, 13, 370000), (15406, 14, 374200), (15406, 15, 374300), (15406, 16, 374400), (15406, 17, 389300), (15406, 18, 393600), (15406, 19, 394000), (15406, 20, 394100), (15406, 21, 394200), (15406, 22, 394300), (15406, 23, 394400), (15406, 24, 394500), (15406, 25, 400200), (15406, 26, 405400), (15406, 28, 405600)) limit 1   /*  NULL  */ ;
